import { serve } from 'https://deno.land/std@0.168.0/http/server.ts'
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2'

const SUPABASE_URL = Deno.env.get('SUPABASE_URL')
const SUPABASE_ANON_KEY = Deno.env.get('SUPABASE_ANON_KEY')
const SERVICE_KEY = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')
if (!SUPABASE_URL || !SUPABASE_ANON_KEY || !SERVICE_KEY) {
  throw new Error('Missing required environment variables')
}

interface Invoice {
  id: number; inv_no: string; date: string; customer_id: number | null
  customer_name: string; customer_address: string; customer_phone: string
  customer_state: string; customer_gstin: string
  subtotal: number; hallmark_total: number; tax_total: number
  adj_bill_id: number | null; adj_amount: number
  discount: number; grand_total: number; round_off: number
  payment_mode: string; cash_amt: number; bank_amt: number
  gold_rate: number; irn: string | null
}
interface InvItem { id: number; item_id: number | null; weight: number; rate_per_gram: number; price: number; tax_amount: number; hallmark_charge: number; sno: number; huid: boolean; huid_code: string; description_extra?: string; material_type?: string; item_master?: { name: string; hsn_code: string; purity: string } | null }
interface DiamondItem { id: number; code: string; description: string; weight: number; mrp: number; hallmark_charge: number; tax_amount: number }
interface Customer { id: number; name: string; address: string; phone: string; state: string; gstin: string; pan: string; pincode: string }
interface Settings { [key: string]: any }

const STATE_CODES: Record<string, string> = {
  'jammu & kashmir': '01', 'himachal pradesh': '02', 'punjab': '03', 'chandigarh': '04',
  'uttarakhand': '05', 'haryana': '06', 'delhi': '07', 'rajasthan': '08',
  'uttar pradesh': '09', 'bihar': '10', 'sikkim': '11', 'arunachal pradesh': '12',
  'nagaland': '13', 'manipur': '14', 'mizoram': '15', 'tripura': '16',
  'meghalaya': '17', 'assam': '18', 'west bengal': '19', 'jharkhand': '20',
  'odisha': '21', 'chhattisgarh': '22', 'madhya pradesh': '23', 'gujarat': '24',
  'daman & diu': '25', 'dadra & nagar haveli': '26', 'maharashtra': '27',
  'andhra pradesh': '28', 'karnataka': '29', 'goa': '30', 'lakshadweep': '31',
  'kerala': '32', 'tamil nadu': '33', 'puducherry': '34', 'andaman & nicobar': '35',
  'telangana': '36', 'ladakh': '38',
}

function stateCode(name: string): string {
  return STATE_CODES[name.toLowerCase().trim()] || '00'
}

function wordsBelow1000(n: number): string {
  const ones = ['','One ','Two ','Three ','Four ','Five ','Six ','Seven ','Eight ','Nine ','Ten ',
    'Eleven ','Twelve ','Thirteen ','Fourteen ','Fifteen ','Sixteen ','Seventeen ','Eighteen ','Nineteen ']
  const tens = ['','','Twenty ','Thirty ','Forty ','Fifty ','Sixty ','Seventy ','Eighty ','Ninety ']
  if (n < 20) return ones[n]
  if (n < 100) return tens[Math.floor(n / 10)] + ones[n % 10]
  return ones[Math.floor(n / 100)] + 'Hundred ' + (n % 100 > 0 ? wordsBelow1000(n % 100) : '')
}

// Indian number to words (Lakh/Crore system)
function amountInWords(n: number): string {
  if (n <= 0) return 'Zero Only'
  const num = Math.round(n * 100) / 100
  let rupees = Math.floor(num)
  let paise = Math.round((num - rupees) * 100)
  if (paise >= 100) { rupees += 1; paise = 0 }
  if (rupees === 0 && paise === 0) return 'Zero Only'

  let result = ''
  if (rupees > 0) {
    const crores = Math.floor(rupees / 10000000)
    const lakhs = Math.floor((rupees % 10000000) / 100000)
    const thousands = Math.floor((rupees % 100000) / 1000)
    const hundreds = rupees % 1000

    if (crores > 0) result += wordsBelow1000(crores) + ' Crore '
    if (lakhs > 0) result += wordsBelow1000(lakhs) + ' Lakh '
    if (thousands > 0) result += wordsBelow1000(thousands) + ' Thousand '
    if (hundreds > 0) result += wordsBelow1000(hundreds) + ' '
    result += 'Rupees '
  }
  if (paise > 0) {
    result += wordsBelow1000(paise) + ' Paise '
  }
  return result.trim() + ' Only'
}

function fmt(n: number | string | null | undefined, dec = 2): string {
  const v = Number(n) || 0
  return v.toLocaleString('en-IN', { minimumFractionDigits: dec, maximumFractionDigits: dec })
}

function fmtWt(n: number | string | null | undefined): string {
  return (Number(n) || 0).toFixed(3)
}

function fmtDate(d: string): string {
  if (!d) return ''
  const dt = new Date(d + 'T00:00:00')
  if (isNaN(dt.getTime())) return ''
  const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec']
  return dt.getDate() + '-' + months[dt.getMonth()] + '-' + String(dt.getFullYear()).slice(-2)
}

function esc(s: string | null | undefined): string {
  if (!s) return ''
  return s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;')
}

async function fetchFrom<T>(path: string): Promise<T> {
  const res = await fetch(SUPABASE_URL + path, {
    headers: { 'apikey': SERVICE_KEY, 'Authorization': 'Bearer ' + SERVICE_KEY }
  })
  if (!res.ok) throw new Error('DB error: ' + path + ' ' + res.status)
  return res.json()
}

function buildHtml(inv: Invoice, items: InvItem[], diamonds: DiamondItem[], customer: Customer | null, s: Settings, adjInvNo?: string): string {
  const shopName = s.shop_name || 'SJS Jewellery'
  const shopAddr = s.shop_address || ''
  const shopAddrHtml = shopAddr.replace('Market, Link Road', 'Market,<br>Link Road')
  const shopGstin = s.shop_gstin || ''
  const shopPhone = s.shop_phone || ''
  const bank: any = s.bank_details || {}
  const bankName = bank.bank_name || 'Bandhan Bank'
  const bankAcHolder = bank.account_holder || 'Sonika Jewellers and Sons'
  const bankAcNo = bank.account_no || '101900008574444'
  const bankIfsc = bank.ifsc || 'BDBL0001779'
  const bankBranch = bank.branch || 'Faridabad Branch, Ground Floor, SCO-32, Sec-16, Huda Market, Old Faridabad, 121002'
  const bankAcType = bank.account_type || 'Current Account'
  const shopPan = s.shop_pan || ''
  const shopCity = s.shop_city || 'Delhi'

  const sellerStateCode = shopGstin ? shopGstin.substring(0, 2) : '07'
  const buyerStateCode = customer?.gstin ? customer.gstin.substring(0, 2) : stateCode(customer?.state || inv.customer_state || '')
  const isInterState = sellerStateCode !== buyerStateCode

  const goodsTaxRate = 3
  const hallTaxRate = 18
  const goodsTaxItems = items.reduce((s, i) => s + Number(i.tax_amount), 0)
  const totalHc = items.reduce((s, i) => s + Number(i.hallmark_charge), 0) + diamonds.reduce((s, i) => s + Number(i.hallmark_charge), 0)
  const hallTaxAmount = Math.max(0, Number(inv.tax_total) - goodsTaxItems)
  const totalWeight = items.reduce((s, i) => s + Number(i.weight), 0) + diamonds.reduce((s, d) => s + Number(d.weight), 0)

  function hsnRows() {
    const hsnMap = new Map<string, { taxable: number; tax: number }>()
    for (const it of items) {
      const hsn = it.material_type === 'silver_925' || it.material_type === 'silver_ornaments' ? '71131130' : it.material_type === 'gold_18k' ? '71131913' : it.item_master?.hsn_code || '71131913'
      const existing = hsnMap.get(hsn) || { taxable: 0, tax: 0 }
      existing.taxable += Number(it.price)
      existing.tax += Number(it.tax_amount)
      hsnMap.set(hsn, existing)
    }
    if (totalHc > 0) {
      const hcHsn = '998346'
      const ex = hsnMap.get(hcHsn) || { taxable: 0, tax: 0 }
      ex.taxable += totalHc
      ex.tax += hallTaxAmount
      hsnMap.set(hcHsn, ex)
    }
    let rows = ''
    for (const [hsn, v] of hsnMap) {
      const rate = v.tax > 0 && v.taxable > 0 ? Math.round((v.tax / v.taxable) * 100) : 0
      rows += `<tr><td class="l">${hsn}</td><td class="r">&#8377;${fmt(v.taxable)}</td><td class="c">${rate}%</td><td class="r">&#8377;${fmt(isInterState ? v.tax : 0)}</td><td class="c">${isInterState ? '' : rate / 2 + '%'}</td><td class="r">&#8377;${fmt(isInterState ? 0 : v.tax / 2)}</td><td class="c">${isInterState ? '' : rate / 2 + '%'}</td><td class="r">&#8377;${fmt(isInterState ? 0 : v.tax / 2)}</td></tr>`
    }
    return rows
  }

  function itemDesc(it: InvItem): string {
    if (!it.item_id && it.description_extra) return esc(it.description_extra)
    let d = esc(it.item_master?.name || 'Item')
    const parts: string[] = []
    if (it.item_master?.purity) parts.push(esc(it.item_master.purity))
    if (it.huid_code) parts.push('HUID: ' + esc(it.huid_code))
    if (parts.length) d += ' (' + parts.join(', ') + ')'
    return d
  }

  function paySummary(): string {
    const c = Number(inv.cash_amt)
    const b = Number(inv.bank_amt)
    const lines: string[] = []
    if (c > 0) lines.push(`Cash: &#8377;${fmt(c)}`)
    if (b > 0) lines.push(`E-Banking: &#8377;${fmt(b)}`)
    return lines.join('<br>')
  }

  const lineRows = items.map((it, i) => {
    const isSilver = !it.item_id && it.material_type !== 'gold_18k'
    const isGold18k = !it.item_id && it.material_type === 'gold_18k'
    return `
<tr class="datarow">
  <td class="c">${i + 1}</td>
  <td><span class="b">${itemDesc(it)}</span></td>
  <td class="c">${isSilver ? '71131130' : isGold18k ? '71131913' : esc(it.item_master?.hsn_code || '')}</td>
  <td class="r" style="white-space: nowrap;">${fmtWt(it.weight)} gm</td>
  <td class="r">${isSilver ? '&#8377;' + fmt(it.rate_per_gram) : '&#8377;' + fmt(it.rate_per_gram)}</td>
  <td class="r b">&#8377;${fmt(it.price)}</td>
</tr>`}).join('\n')

  const diamondRows = diamonds.map((d, i) => `
<tr class="datarow">
  <td class="c">${items.length + i + 1}</td>
  <td><span class="b">Diamond${d.code ? ' (' + esc(d.code) + ')' : ''}</span><br><span class="sm">${esc(d.description || '')}</span></td>
  <td class="c">&mdash;</td>
  <td class="r" style="white-space: nowrap;">${fmtWt(d.weight)} gm</td>
  <td class="r">&#8377;${fmt(d.mrp)}</td>
  <td class="r b">&#8377;${fmt(d.mrp)}</td>
</tr>`).join('\n')

  const igstGoods = isInterState ? goodsTaxItems : 0
  const cgstGoods = isInterState ? 0 : goodsTaxItems / 2
  const sgstGoods = isInterState ? 0 : goodsTaxItems / 2
  const igstHall = isInterState && hallTaxAmount > 0 ? hallTaxAmount : 0
  const cgstHall = !isInterState && hallTaxAmount > 0 ? hallTaxAmount / 2 : 0
  const sgstHall = !isInterState && hallTaxAmount > 0 ? hallTaxAmount / 2 : 0

  const summaryRows = `
${totalHc > 0 ? `<tr class="subrow hm-gap"><td></td><td class="r i">Hallmark Charges</td><td class="c">998346</td><td></td><td></td><td class="r b">&#8377;${fmt(totalHc)}</td></tr>` : ''}
${isInterState ? `
<tr class="subrow"><td></td><td class="r i">IGST @ ${goodsTaxRate}%</td><td></td><td></td><td></td><td class="r b">&#8377;${fmt(igstGoods)}</td></tr>
` : `
<tr class="subrow"><td></td><td class="r i">CGST @ ${goodsTaxRate / 2}%</td><td></td><td></td><td></td><td class="r b">&#8377;${fmt(cgstGoods)}</td></tr>
<tr class="subrow"><td></td><td class="r i">SGST @ ${goodsTaxRate / 2}%</td><td></td><td></td><td></td><td class="r b">&#8377;${fmt(sgstGoods)}</td></tr>
`}
${hallTaxAmount > 0 ? isInterState ? `
<tr class="subrow"><td></td><td class="r i">IGST @ ${hallTaxRate}% (Hallmark)</td><td></td><td></td><td></td><td class="r b">&#8377;${fmt(igstHall)}</td></tr>
` : `
<tr class="subrow"><td></td><td class="r i">CGST @ ${hallTaxRate / 2}% (Hallmark)</td><td></td><td></td><td></td><td class="r b">&#8377;${fmt(cgstHall)}</td></tr>
<tr class="subrow"><td></td><td class="r i">SGST @ ${hallTaxRate / 2}% (Hallmark)</td><td></td><td></td><td></td><td class="r b">&#8377;${fmt(sgstHall)}</td></tr>
` : ''}
${Number(inv.discount) > 0 ? `<tr class="subrow"><td></td><td class="r i">Discount</td><td></td><td></td><td></td><td class="r b">(-)&#8377;${fmt(inv.discount)}</td></tr>` : ''}
${inv.adj_bill_id && Number(inv.adj_amount) > 0 ? `<tr class="subrow"><td></td><td class="r i">Less : Adj. (${esc(adjInvNo || '')})</td><td></td><td></td><td></td><td class="r b">(-)&#8377;${fmt(inv.adj_amount)}</td></tr>` : ''}
${Number(inv.round_off) !== 0 ? `<tr class="subrow"><td></td><td class="r i">Round Off</td><td></td><td></td><td></td><td class="r b">${Number(inv.round_off) > 0 ? '' : '(-)'}&#8377;${fmt(Math.abs(Number(inv.round_off)))}</td></tr>` : ''}
<tr class="totalrow">
  <td colspan="2" class="r">Total</td><td></td>
  <td class="r">${fmtWt(totalWeight)} gm</td><td></td>
  <td class="r">&#8377;${fmt(inv.grand_total)}</td>
</tr>`

  const _hasDiscount = Number(inv.discount) > 0
  const _hasAdj = inv.adj_bill_id && Number(inv.adj_amount) > 0

  return `<!DOCTYPE html>
<html><head><meta charset="utf-8"><title>SJS_${esc(inv.inv_no)}</title>
<style>
@page { margin: 7mm; }
* { margin: 0; padding: 0; box-sizing: border-box; }
body { font-family: Arial, Helvetica, sans-serif; font-size: 13px; color: #222; background: #e5e5e5; padding: 5px 0; }
.invoice { width: 100%; max-width: 210mm; margin: 0 auto; border: 1px solid #bbb; page-break-after: always; position: relative; }
table { width: 100%; border-collapse: collapse; }
td, th { border: 0.5px solid #bbb; padding: 4px 5px; vertical-align: top; }
th { background: #ddd; font-weight: 700; text-align: center; white-space: nowrap; color: #222; font-size: 11px; }
.l { text-align: left; } .r { text-align: right; } .c { text-align: center; }
.b { font-weight: 700; } .i { font-style: italic; }
.sm { font-size: 11px; color: #555; }
.muted { color: #666; }
.rl { color: #666; font-size: 11px; }

/* Header */
.hdr { display: flex; align-items: center; padding: 0; border-bottom: 1px solid #bbb; }
.hdr .logo { width: 85px; height: 85px; margin: -25px 12px -25px 0; flex-shrink: 0; }
.hdr .shop-info { flex: 1; text-align: left; padding: 8px 0; }
.hdr .name { font-size: 22px; font-weight: 700; color: #111; letter-spacing: 1px; }
.hdr .addr { font-size: 11px; color: #555; margin-top: 3px; }
.title-row { text-align: center; padding: 4px 0; border-bottom: 1px solid #bbb; }
.title-row .t { font-size: 16px; font-weight: 700; letter-spacing: 4px; text-transform: uppercase; color: #222; }

/* Seller / Buyer blocks */
.seller { font-size: 11px; padding: 6px 8px; }
.seller .sn { font-size: 15px; }
.buyer { font-size: 11px; padding: 6px 8px; }
.buyer .bl { font-size: 11px; color: #555; }

/* Table rows */
.lines { page-break-inside: auto; }
.lines thead { display: table-header-group; }
.lines tr { page-break-inside: avoid; }
.datarow td { padding: 3px 5px; font-size: 11px; border-top: none; border-bottom: none; }
.subrow td { padding: 1px 5px; font-size: 10px; border-top: none; border-bottom: none; color: #444; }
.subrow td:first-child { border-left: none; }
.subrow td:last-child { border-right: none; }
.hm-gap td { padding-top: 10px; }
.totalrow td { padding: 4px 5px; font-weight: 700; font-size: 12px; border-top: 2px solid #444; border-bottom: none; }

/* Bottom sections */
.words { font-size: 11px; line-height: 1.3; }
.hsn-tbl { font-size: 10px; }
.footer { font-size: 10px; color: #555; }
.sig { padding: 4px 8px 2px; }
.bot { text-align: center; font-size: 10px; color: #444; font-style: italic; padding: 4px; border-top: 1px solid #bbb; line-height: 1.4; }
</style></head><body>
<div class="invoice">

<div class="hdr">
  <img class="logo" src="data:image/svg+xml;base64," />
  <div class="shop-info">
    <div class="name">${esc(shopName).toUpperCase()}</div>
    <div class="addr">${shopAddrHtml}</div>
  </div>
</div>
<div class="title-row">
  <div class="t">Tax Invoice</div>
</div>

<!-- Seller (left) + Buyer (left) + Meta panel (right, rowspan 2) -->
<table>
<tr>
  <td class="seller" style="width: 50%; vertical-align: top;">
    <div class="sn b">${esc(shopName).toUpperCase()}</div>
    <div class="sm">${shopAddrHtml}</div>
    <div class="sm">State: ${esc(s.shop_state || 'Delhi')} (Code: ${sellerStateCode})</div>
    <div class="sm">Contact: ${esc(shopPhone)}</div>
  </td>
  <td rowspan="2" style="width: 50%; padding: 0; border: none;">
    <table style="width: 100%;">
      <tr><td class="l" style="font-weight: 700; font-size: 11px;">Invoice No.</td><td class="l" style="font-weight: 700; font-size: 11px;">Dated</td></tr>
      <tr><td class="l b">${esc(inv.inv_no)}</td><td class="l b">${fmtDate(inv.date)}</td></tr>
      <tr><td class="l rl">Delivery Note</td><td class="l b">Mode/Terms of Payment - ${esc(inv.payment_mode)}</td></tr>
      <tr><td class="l rl">Dispatched through : By Hand</td><td class="l rl">Destination</td></tr>
      <tr><td class="l rl">Bill of Lading/LR-RR No.</td><td class="l rl">Motor Vehicle No.</td></tr>
      <tr><td class="l sm">dt. ${fmtDate(inv.date)}</td><td class="l"></td></tr>
      <tr><td colspan="2" class="l rl">Terms of Delivery</td></tr>
      ${_hasDiscount ? `
      <tr><td class="l rl">Discount</td><td class="l rl"></td></tr>
      <tr><td class="l"></td><td class="r b">(-)&#8377;${fmt(inv.discount)}</td></tr>` : ''}
      ${_hasAdj ? `
      <tr><td class="l rl">Adj. Bill No.</td><td class="l rl"></td></tr>
      <tr><td class="l b">${esc(adjInvNo || '')}</td><td class="l"></td></tr>
      <tr><td class="l rl">Adj. Amount</td><td class="l rl"></td></tr>
      <tr><td class="l"></td><td class="r b">(-)&#8377;${fmt(inv.adj_amount)}</td></tr>` : ''}
      <tr><td class="l rl">Gold Rate</td><td class="l b">₹${fmt(Number(inv.gold_rate) || 0)}/10gm</td></tr>
    </table>
  </td>
</tr>
<tr>
  <td class="buyer" style="width: 50%; vertical-align: top; border-top: 1.5px solid #333;">
    <div class="bl b">Buyer (Bill to)</div>
    <div class="b" style="font-size: 12px; margin-top: 2px;">${esc(customer?.name || inv.customer_name)}</div>
    <div class="sm">${esc(customer?.address || inv.customer_address || '')}</div>
    ${(customer?.gstin || inv.customer_gstin) ? `<div class="sm">GSTIN/UIN: ${esc(customer?.gstin || inv.customer_gstin)}</div>` : ''}
    ${customer?.pan ? `<div class="sm">PAN/IT No: ${esc(customer.pan)}</div>` : ''}
    <div class="sm">State: ${esc(customer?.state || inv.customer_state)} (Code: ${buyerStateCode})</div>
    <div class="sm">Place of Supply: ${esc(customer?.state || inv.customer_state)}</div>
  </td>
</tr>
</table>

<!-- Line items -->
<table class="lines">
<thead><tr>
  <th style="width: 30px;">Sl No.</th>
  <th style="width: 250px;">Description of Goods and Services</th>
  <th style="width: 72px;">HSN/SAC</th>
  <th style="width: 68px;">Quantity</th>
  <th style="width: 82px;">Rate (&#8377;)</th>
  <th style="width: 88px;">Amount</th>
</tr></thead>
<tbody>
${lineRows}
${diamondRows}
${summaryRows}
</tbody></table>

<!-- HSN summary + Amount in words (same table = same width) -->
<table class="hsn-tbl" style="width: 100%;">
  <thead><tr>
    <th>HSN/SAC</th>
    <th>Taxable Value</th>
    <th>IGST%</th><th>IGST Amt</th>
    <th>CGST%</th><th>CGST Amt</th>
    <th>SGST%</th><th>SGST Amt</th>
  </tr></thead>
  <tbody>
    ${hsnRows()}
    <tr style="font-weight: 700; border-top: 0.5px solid #444;">
      <td class="l">Total</td>
      <td class="r">&#8377;${fmt(Number(inv.subtotal) + totalHc)}</td>
      <td></td><td class="r">&#8377;${fmt(isInterState ? inv.tax_total : 0)}</td>
      <td></td><td class="r">&#8377;${fmt(isInterState ? 0 : inv.tax_total / 2)}</td>
      <td></td><td class="r">&#8377;${fmt(isInterState ? 0 : inv.tax_total / 2)}</td>
    </tr>
    <tr><td colspan="8" style="padding: 0; border: none;">
          <table style="width: 100%; font-size: 10px; border-collapse: collapse; border: 0.5px solid #444;">
        <tr>
          <th style="width: 50%; font-size: 10px; padding: 4px 6px; background: #ddd;">Amount Chargeable (in words) <span class="muted" style="font-size: 8px;">E. &amp; O.E.</span></th>
          <th style="width: 50%; font-size: 10px; padding: 4px 6px; background: #ddd;">Tax Amount (in words)</th>
        </tr>
        <tr>
          <td style="padding: 4px 6px; text-align: center; font-weight: 700; font-size: 11px;">${amountInWords(Number(inv.grand_total))}</td>
          <td style="padding: 4px 6px; text-align: center; font-weight: 700; font-size: 11px;">${amountInWords(Number(inv.tax_total))}</td>
        </tr>
      </table>
    </td></tr>
  </tbody>
</table>

<!-- Company Info + Bank Details + Payment -->
<table class="footer"><tr>
<td style="width: 100%; border: none; padding: 6px 8px; vertical-align: top;">
  <div style="margin-top: 12px;"><span style="font-weight: 700; font-size: 12px;">Bank Details</span></div>
  <table style="width: auto; font-size: 11px; border-collapse: collapse;">
    <tr><td style="border: 0.5px solid #bbb; padding: 2px 5px; white-space: nowrap; font-weight: 700;">Bank</td><td style="border: 0.5px solid #bbb; padding: 2px 5px;">${esc(bankName)}</td></tr>
    <tr><td style="border: 0.5px solid #bbb; padding: 2px 5px; white-space: nowrap; font-weight: 700;">A/c Type</td><td style="border: 0.5px solid #bbb; padding: 2px 5px;">${esc(bankAcType)}</td></tr>
    <tr><td style="border: 0.5px solid #bbb; padding: 2px 5px; white-space: nowrap; font-weight: 700;">A/c Holder</td><td style="border: 0.5px solid #bbb; padding: 2px 5px;">${esc(bankAcHolder)}</td></tr>
    <tr><td style="border: 0.5px solid #bbb; padding: 2px 5px; white-space: nowrap; font-weight: 700;">A/c No.</td><td style="border: 0.5px solid #bbb; padding: 2px 5px;">${esc(bankAcNo)}</td></tr>
    <tr><td style="border: 0.5px solid #bbb; padding: 2px 5px; white-space: nowrap; font-weight: 700;">Branch</td><td style="border: 0.5px solid #bbb; padding: 2px 5px;">${esc(bankBranch).replace(', Sec-16', ',<br>Sec-16')}</td></tr>
    <tr><td style="border: 0.5px solid #bbb; padding: 2px 5px; white-space: nowrap; font-weight: 700;">IFSC</td><td style="border: 0.5px solid #bbb; padding: 2px 5px;">${esc(bankIfsc)}</td></tr>
    ${shopPan ? `<tr><td style="border: 0.5px solid #bbb; padding: 2px 5px; white-space: nowrap; font-weight: 700;">Pan No.</td><td style="border: 0.5px solid #bbb; padding: 2px 5px;">${esc(shopPan)}</td></tr>` : ''}
  </table>
  <table style="width: 100%; border: none; border-collapse: collapse;">
    <tr>
      <td style="border: none; padding: 0; vertical-align: top; width: 33.33%; white-space: nowrap;">
        <div style="margin-top: 12px;"><span style="font-weight: 700; font-size: 12px;">Payment Mode:</span></div>
        <div style="font-size: 12px; margin-top: 2px;">${paySummary()}</div>
      </td>
      <td style="border: none; padding: 0; width: 33.33%;"></td>
      <td style="border: none; padding: 0; width: 33.33%;"></td>
    </tr>
  </table>
</td>
</tr></table>

    <!-- Floating stamp + signature — positioned relative to .invoice -->
    <div style="position: absolute; bottom: 30px; right: -4px; width: 220px; height: 180px; z-index: -1; pointer-events: none;">
      <img src="data:image/svg+xml;base64," style="position: absolute; right: 0; top: 0; width: 200px; z-index: 1;" />
      <img src="data:image/svg+xml;base64," style="position: absolute; right: 55px; top: 45px; width: 142px; z-index: 2; transform: rotate(-3deg);" />
    </div>
<!-- Signatures -->
<table><tr>
<td class="sig" style="width: 33%; border: none;"></td>
<td class="sig" style="width: 34%; border: none; text-align: center;">
  <div style="margin-bottom: 10px;"></div>
  <div class="muted">Customer's Seal and Signature</div>
</td>
<td class="sig" style="width: 33%; border: none; text-align: right;">
  <div class="muted">for <span class="b" style="color:#222;">${esc(shopName)}</span></div>
  <div style="margin-top: 10px;"><span class="b" style="color:#222;">Authorised Signatory</span></div>
</td>
</tr></table>
<div class="bot">
  SUBJECT TO ${esc(shopCity).toUpperCase()} JURISDICTION &nbsp;|&nbsp; This is a Computer Generated Invoice<br>
  Thanks for shopping with us!
</div>

</div>
</body></html>`
}

function corsHeaders(req: Request) {
  const origin = req.headers.get('Origin') || SUPABASE_URL
  return {
    'Access-Control-Allow-Origin': origin,
    'Access-Control-Allow-Methods': 'POST, OPTIONS',
    'Access-Control-Allow-Headers': 'authorization, content-type, x-client-info, apikey, x-connection-protocol',
  }
}

serve(async (req) => {
  const CORS_HEADERS = corsHeaders(req)
  if (req.method === 'OPTIONS') return new Response('ok', { headers: CORS_HEADERS })

  if (req.method !== 'POST') return new Response('Method not allowed', { status: 405, headers: CORS_HEADERS })
  const authHeader = req.headers.get('Authorization')
  if (!authHeader) return new Response('Unauthorized', { status: 401, headers: CORS_HEADERS })
  const userClient = createClient(SUPABASE_URL, SUPABASE_ANON_KEY, { global: { headers: { Authorization: authHeader } } })
  const { data: { user }, error: authErr } = await userClient.auth.getUser()
  if (authErr || !user) return new Response('Unauthorized', { status: 401, headers: CORS_HEADERS })

  try {
    const body = await req.json()
    const invoiceId = Number(body.invoiceId)
    if (!invoiceId) return new Response('Missing invoiceId', { status: 400, headers: CORS_HEADERS })

    const [invArr, settingsArr] = await Promise.all([
      fetchFrom<any[]>('/rest/v1/invoices?select=*&id=eq.' + invoiceId),
      fetchFrom<any[]>('/rest/v1/settings?select=key,value'),
    ])
    if (!invArr || invArr.length === 0) return new Response('Invoice not found', { status: 404, headers: CORS_HEADERS })
    const inv = invArr[0] as Invoice

    const [items, diamonds, custArr, adjArr] = await Promise.all([
      fetchFrom<any[]>('/rest/v1/invoice_items?select=*,item_master!left(name,hsn_code,purity)&invoice_id=eq.' + invoiceId + '&order=sno.asc'),
      fetchFrom<any[]>('/rest/v1/diamond_items?select=*&invoice_id=eq.' + invoiceId),
      inv.customer_id ? fetchFrom<any[]>('/rest/v1/customers?select=*&id=eq.' + inv.customer_id) : Promise.resolve([]),
      inv.adj_bill_id ? fetchFrom<any[]>('/rest/v1/inward_supply_vouchers?select=inv_no&id=eq.' + inv.adj_bill_id) : Promise.resolve([]),
    ])

    const settings: Settings = {}
    for (const s of settingsArr) {
      try { settings[s.key] = typeof s.value === 'string' ? JSON.parse(s.value) : s.value }
      catch { settings[s.key] = s.value }
    }

    const customer = custArr && custArr.length > 0 ? custArr[0] as Customer : null
    const adjInvNo = adjArr && adjArr.length > 0 ? adjArr[0].inv_no : undefined
    const html = buildHtml(inv, items || [], diamonds || [], customer, settings, adjInvNo)

    return new Response(html, {
      headers: { 'Content-Type': 'text/html; charset=utf-8', ...CORS_HEADERS },
    })
  } catch (_err: any) {
    const msg = _err?.message || _err?.toString() || 'Unknown error'
    console.error('generate-invoice-pdf error:', msg)
    return new Response(msg, { status: 500, headers: CORS_HEADERS })
  }
})
